using UnityEngine.XR.Hands;

void Update() {
    var hand = XRHandSubsystem.GetHand(Handedness.Right);
    float pinchStrength = hand.GetFingerPinchStrength(
        XRHandFingerID.Index
    );
    if (pinchStrength &gt; 0.9f) {
        OnPinch();
    }
}

